pub(crate) fn catalogue() -> AggregateCatalogue {
    AggregateCatalogue::new(
        SIGNATURES
            .iter()
            .map(|(name, parameters)| {
                let arguments = parameters
                    .iter()
                    .map(|parameter| {
                        if *parameter == "*" {
                            AggregateArg::Any
                        } else {
                            AggregateArg::Type((*parameter).to_string())
                        }
                    })
                    .collect();
                ((*name).to_string(), arguments)
            })
            .collect(),
    )
}
